import{_ as s,o as e,c as t,a3 as i}from"./chunks/framework.WFmvnizL.js";const k=JSON.parse('{"title":"How to migrate, back up, and restore data","description":"Back up, migrate, and restore Nezha Monitoring Dashboard using the current installation script layout, with Docker, systemd, and OpenRC stop/start commands and recovery checks.","frontmatter":{"description":"Back up, migrate, and restore Nezha Monitoring Dashboard using the current installation script layout, with Docker, systemd, and OpenRC stop/start commands and recovery checks.","outline":"deep"},"headers":[],"relativePath":"en_US/guide/q5.md","filePath":"en_US/guide/q5.md","lastUpdated":1792674226000}'),n={name:"en_US/guide/q5.md"};function r(o,a,h,d,l,p){return e(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="how-to-migrate-back-up-and-restore-data" tabindex="-1">How to migrate, back up, and restore data <a class="header-anchor" href="#how-to-migrate-back-up-and-restore-data" aria-label="Permalink to &quot;How to migrate, back up, and restore data&quot;">​</a></h1><p><strong>Stop Dashboard before backing up, then use the commands for your deployment to start it after restoration.</strong> The current installation script has no separate “Stop Dashboard” or “Start Dashboard” menu entries.</p><p>“Restart and Update Dashboard” pulls an image or downloads the latest binary; <strong>it is not a restart-only operation</strong>. Do not use it instead of the stop/start commands below. Do not use “Uninstall Dashboard” either: it removes the Dashboard directory.</p><h2 id="_1-identify-your-deployment-and-backup-scope" tabindex="-1">1. Identify your deployment and backup scope <a class="header-anchor" href="#_1-identify-your-deployment-and-backup-scope" aria-label="Permalink to &quot;1. Identify your deployment and backup scope&quot;">​</a></h2><p>The current script supports Docker and standalone installations. Its default Dashboard directory is <code>/opt/nezha/dashboard</code>:</p><ul><li><strong>Docker:</strong> Uses <code>docker-compose.yaml</code> in that directory, with service name <code>dashboard</code> and <code>./data</code> mounted at <code>/dashboard/data</code> inside the container.</li><li><strong>Standalone:</strong> Runs the <code>app</code> binary in that directory as the <code>nezha-dashboard</code> service, managed by systemd or OpenRC.</li><li><strong>Core data:</strong> <code>data/</code> contains configuration in <code>config.yaml</code>, the default database <code>sqlite.db</code>, and other runtime data. Back up the whole directory, not just the main database file.</li></ul><p>The instructions below use the script defaults. If you customized the database location, configuration path, or <code>tsdb.data_path</code>, or use external mounts or symbolic links, back up the actual data separately. Reverse-proxy configuration, certificates, and systemd/OpenRC service files are outside the Dashboard directory and also need separate copies.</p><div class="warning custom-block"><p class="custom-block-title">Separate migration from upgrades</p><p>This guide covers migration and recovery between compatible V2 deployments. Prefer restoring with the same Dashboard version as the source, then upgrading separately. The installation script downloads the latest release; it is not a fixed-version recovery tool. For older product generations, consult their migration instructions rather than overwriting data directly.</p></div><h2 id="_2-stop-dashboard-on-the-source-server" tabindex="-1">2. Stop Dashboard on the source server <a class="header-anchor" href="#_2-stop-dashboard-on-the-source-server" aria-label="Permalink to &quot;2. Stop Dashboard on the source server&quot;">​</a></h2><p><strong>Run only the command group matching your deployment.</strong> Stop Dashboard, not the Agents on individual servers. Monitoring and alerting will be temporarily unavailable during migration.</p><h3 id="docker" tabindex="-1">Docker <a class="header-anchor" href="#docker" aria-label="Permalink to &quot;Docker&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/nezha/dashboard/docker-compose.yaml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 60</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dashboard</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/nezha/dashboard/docker-compose.yaml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ps</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -a</span></span></code></pre></div><p>Confirm the service has stopped. If you use the standalone Compose command, replace <code>docker compose</code> with <code>docker-compose</code> throughout these examples.</p><h3 id="standalone-systemd" tabindex="-1">Standalone: systemd <a class="header-anchor" href="#standalone-systemd" aria-label="Permalink to &quot;Standalone: systemd&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nezha-dashboard</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> is-active</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nezha-dashboard</span></span></code></pre></div><p>The expected output is <code>inactive</code>; a nonzero exit status from this check is normal when the service is stopped.</p><h3 id="standalone-openrc" tabindex="-1">Standalone: OpenRC <a class="header-anchor" href="#standalone-openrc" aria-label="Permalink to &quot;Standalone: OpenRC&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rc-service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nezha-dashboard</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rc-service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nezha-dashboard</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><p>Confirm the service is stopped. Investigate failed stops or abnormal exits in logs before proceeding; an archive copied from a running data directory is not necessarily a consistent backup.</p><h2 id="_3-create-and-store-a-backup" tabindex="-1">3. Create and store a backup <a class="header-anchor" href="#_3-create-and-store-a-backup" aria-label="Permalink to &quot;3. Create and store a backup&quot;">​</a></h2><p>Run this example on the source server. Choose a new filename for each subsequent backup so you do not overwrite an earlier archive.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 700</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /root/nezha-backup</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -czpf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /root/nezha-backup/dashboard-backup.tar.gz</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -C</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/nezha</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dashboard</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -tzf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /root/nezha-backup/dashboard-backup.tar.gz</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /dev/null</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sha256sum</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /root/nezha-backup/dashboard-backup.tar.gz</span></span></code></pre></div><p>Confirm the commands succeed. Store the archive and checksum on another machine or backup storage. Use a protected transfer method and compare checksums after copying. Backups contain configuration, database contents, and credentials; keep them out of public download directories.</p><ul><li><strong>Backup only:</strong> Start the original Dashboard using section 5 once the backup is complete.</li><li><strong>Server migration:</strong> Keep the old Dashboard stopped while restoring on the target, so two instances do not run tasks and send notifications at the same time.</li></ul><h2 id="_4-restore-on-the-target-server" tabindex="-1">4. Restore on the target server <a class="header-anchor" href="#_4-restore-on-the-target-server" aria-label="Permalink to &quot;4. Restore on the target server&quot;">​</a></h2><ol><li><strong>Prepare the runtime.</strong> Set up Docker/Compose, or a standalone binary and service files suitable for the target CPU architecture. You can follow <a href="/en_US/guide/dashboard.html">Install Dashboard</a> in an empty directory to establish a deployment, but confirm version compatibility and stop the new instance before restoring. Copying the directory alone does not register a standalone service; do not reuse an <code>app</code> binary built for a different CPU architecture.</li><li><strong>Preserve existing target data.</strong> If the target already has data, stop it, make a separate backup, and move its current <code>data/</code> to an unused backup location. Do not merge two database directories.</li><li><strong>Extract into a temporary directory.</strong> Inspect the archive, then restore its entire <code>dashboard/data/</code> as <code>/opt/nezha/dashboard/data/</code> on the target, preserving permissions and ownership. Retain the binary and service files appropriate for the target. For Docker, review the image version, ports, and mounts instead of blindly overwriting the target configuration.</li><li><strong>Check external dependencies.</strong> Restore separately backed-up TSDB or other external data. Check the service user&#39;s read/write permissions, configuration paths, reverse proxy, certificates, and firewall. If the address or port changes, update DNS and Agent connection settings as well.</li></ol><div class="tip custom-block"><p class="custom-block-title">Start directly after restoring</p><p>Do not select “Install Dashboard” or “Modify Dashboard Configuration” after restoring data: the current script regenerates and overwrites <code>data/config.yaml</code>, and rewrites the Compose file for Docker deployments. Start the service with the commands below instead.</p></div><h2 id="_5-start-and-verify" tabindex="-1">5. Start and verify <a class="header-anchor" href="#_5-start-and-verify" aria-label="Permalink to &quot;5. Start and verify&quot;">​</a></h2><p>Select the commands for your deployment. The Docker commands below start an existing container without pulling a new image. If the target has only a Compose file and no container yet, verify its image version and mounts, then create the container with <code>sudo docker compose -f /opt/nezha/dashboard/docker-compose.yaml up -d dashboard</code>.</p><h3 id="docker-1" tabindex="-1">Docker <a class="header-anchor" href="#docker-1" aria-label="Permalink to &quot;Docker&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/nezha/dashboard/docker-compose.yaml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dashboard</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/nezha/dashboard/docker-compose.yaml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tail</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dashboard</span></span></code></pre></div><h3 id="standalone-systemd-1" tabindex="-1">Standalone: systemd <a class="header-anchor" href="#standalone-systemd-1" aria-label="Permalink to &quot;Standalone: systemd&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nezha-dashboard</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nezha-dashboard</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-pager</span></span></code></pre></div><p>If you manually added or changed the systemd service file, run <code>sudo systemctl daemon-reload</code> before starting it.</p><h3 id="standalone-openrc-1" tabindex="-1">Standalone: OpenRC <a class="header-anchor" href="#standalone-openrc-1" aria-label="Permalink to &quot;Standalone: OpenRC&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rc-service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nezha-dashboard</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rc-service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nezha-dashboard</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><p>After restoration, check that:</p><ul><li>Your original account works and the server inventory, settings, alerts, and tasks remain present.</li><li>Agents reconnect and server state and monitoring data continue to update.</li><li>Online history and any enabled TSDB history match the backup point.</li><li>Logs show no database, permission, or configuration-reading errors, and domain and reverse-proxy access work.</li></ul><p>Keep the old server and backup until verification is complete. To roll back, stop the new Dashboard before switching back to the original deployment and connection address. Do not open a database migrated by a newer release directly with an older binary.</p><h2 id="script-references" tabindex="-1">Script references <a class="header-anchor" href="#script-references" aria-label="Permalink to &quot;Script references&quot;">​</a></h2><p>Paths, service names, and menu behavior are based on the official <a href="https://github.com/nezhahq/scripts/blob/main/install_en.sh" target="_blank" rel="noreferrer">English installation script</a>, <a href="https://github.com/nezhahq/scripts/blob/main/extras/docker-compose.yaml" target="_blank" rel="noreferrer">Compose template</a>, <a href="https://github.com/nezhahq/scripts/blob/main/services/nezha-dashboard.service" target="_blank" rel="noreferrer">systemd unit</a>, and <a href="https://github.com/nezhahq/scripts/blob/main/services/nezha-dashboard" target="_blank" rel="noreferrer">OpenRC service</a>.</p>`,41)])])}const g=s(n,[["render",r]]);export{k as __pageData,g as default};
